async function saveGeneralObservation(){
  const o=d3.observation,model=currentVersion().model,stock=model.stocks.find(x=>x.id===o.stock);
  if(!o.checked)throw new Error("Confirma que el valor figura en la fuente.");
  const value=exactQuantity(o.value.trim().replace(",","."));if(!/^\d+\/\d+$/.test(value))throw new Error("Escribe el valor medido como número no negativo, con punto decimal si hace falta.");
  const timestamp=new Date(o.time);if(Number.isNaN(timestamp.getTime()))throw new Error("Indica la fecha y hora de la medición.");
  if(o.source.trim().length<8)throw new Error("Indica la fuente de la medición.");
  const payload={base_version:activeCase().current_version,policy_id:o.policy,scenario_id:o.scenario,day:Number(o.day),variable:stock.id,value,unit:stock.unit,observed_at:timestamp.toISOString(),source:o.source.trim()};
  const signature=JSON.stringify(payload);if(o.pending?.signature!==signature)o.pending={signature,key:crypto.randomUUID()};
  const response=await api(`/api/cases/${encodeURIComponent(activeCase().id)}/observations`,{...payload,idempotency_key:o.pending.key});
  ui.observed=response.observation;d3.observation=null;ui.evaluation=null;ui.evaluationVersion=null;await refresh();render();announce("Medición conservada en una versión nueva. La predicción anterior queda intacta; calcula de nuevo para registrar otra.");
}
